import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"新旧企业家思维对比 & 年轻人破局框架","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/career-observation/old-vs-new-entrepreneur-mindset.md","filePath":"topics/career-observation/old-vs-new-entrepreneur-mindset.md"}'),d={name:"topics/career-observation/old-vs-new-entrepreneur-mindset.md"};function i(n,t,s,l,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="新旧企业家思维对比-年轻人破局框架" tabindex="-1">新旧企业家思维对比 &amp; 年轻人破局框架 <a class="header-anchor" href="#新旧企业家思维对比-年轻人破局框架" aria-label="Permalink to &quot;新旧企业家思维对比 &amp; 年轻人破局框架&quot;">​</a></h1><blockquote><p>整理自媒体博主 x 36年地产企业家访谈 日期：2026-08-04</p></blockquote><hr><h2 id="一、行业洞察-房地产的-后开发时代" tabindex="-1">一、行业洞察：房地产的&quot;后开发时代&quot; <a class="header-anchor" href="#一、行业洞察-房地产的-后开发时代" aria-label="Permalink to &quot;一、行业洞察：房地产的&quot;后开发时代&quot;&quot;">​</a></h2><h3 id="时代划分" tabindex="-1">时代划分 <a class="header-anchor" href="#时代划分" aria-label="Permalink to &quot;时代划分&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>触发条件</th><th>核心模式</th></tr></thead><tbody><tr><td><strong>开发时代</strong></td><td>人均GDP &lt; 1万美元</td><td>住宅开发销售（解决0→1）</td></tr><tr><td><strong>后开发时代</strong></td><td>人均GDP ≥ 1万美元</td><td>多元化资产经营与管理（解决1→多）</td></tr></tbody></table><h3 id="后开发时代的特征" tabindex="-1">后开发时代的特征 <a class="header-anchor" href="#后开发时代的特征" aria-label="Permalink to &quot;后开发时代的特征&quot;">​</a></h3><ul><li><strong>业务重心迁移</strong>：从&quot;建房卖房&quot;到&quot;运营管理资产&quot;</li><li><strong>市场现实</strong>：全国超100万亿元房产处于不盈利状态 <ul><li>不是行业衰退，是存量市场</li><li>需要新的运营能力和资产管理能力</li><li>巨大的资产运营机会窗口</li></ul></li></ul><h3 id="相关主题" tabindex="-1">相关主题 <a class="header-anchor" href="#相关主题" aria-label="Permalink to &quot;相关主题&quot;">​</a></h3><ul><li>经济周期：<a href="/zhishiku-reading/topics/economic-cycles/">economic-cycles</a></li><li>投资方法：<a href="/zhishiku-reading/topics/stock-investment/">investment-methods</a>（资产配置视角）</li></ul><hr><h2 id="二、代际认知框架-古早类-vs-ai时代企业家" tabindex="-1">二、代际认知框架：古早类 vs AI时代企业家 <a class="header-anchor" href="#二、代际认知框架-古早类-vs-ai时代企业家" aria-label="Permalink to &quot;二、代际认知框架：古早类 vs AI时代企业家&quot;">​</a></h2><h3 id="核心对比矩阵" tabindex="-1">核心对比矩阵 <a class="header-anchor" href="#核心对比矩阵" aria-label="Permalink to &quot;核心对比矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>古早类企业家</th><th>AI时代企业家</th></tr></thead><tbody><tr><td><strong>成长环境</strong></td><td>体制转型期，规则模糊</td><td>技术成熟期，规则清晰</td></tr><tr><td><strong>思维原点</strong></td><td>政策、机会、人脉（外部资源）</td><td>产品、技术、客户（原点思维）</td></tr><tr><td><strong>核心竞争力</strong></td><td>处理复杂社会关系</td><td>理性分析 + 数据驱动</td></tr><tr><td><strong>突破方式</strong></td><td>冒险精神，&quot;清华北大不如胆子大&quot;</td><td>技术能力 + 专业深耕</td></tr><tr><td><strong>适合群体</strong></td><td>外向、敢拼、擅长社交</td><td>理工男、宅男也能成功</td></tr><tr><td><strong>风险来源</strong></td><td>政策不确定性</td><td>技术迭代 / 市场竞争</td></tr><tr><td><strong>未来趋势</strong></td><td>不适应复杂法律环境，逐渐被淘汰</td><td>社会科技进步的主要推动力</td></tr></tbody></table><h3 id="洞察" tabindex="-1">洞察 <a class="header-anchor" href="#洞察" aria-label="Permalink to &quot;洞察&quot;">​</a></h3><blockquote><p>底层逻辑变了，成功的条件重组了。</p></blockquote><ul><li>&quot;胆子大&quot;在规则缺失时代是核心竞争力</li><li>规则化社会中，<strong>原点思维（产品/技术/客户）</strong> 成为更稳健的路径</li><li>技术工具降低了创业门槛，为普通人（理工男、宅男）提供了更多机会</li></ul><hr><h2 id="三、年轻人破局框架-三字诀" tabindex="-1">三、年轻人破局框架：三字诀 <a class="header-anchor" href="#三、年轻人破局框架-三字诀" aria-label="Permalink to &quot;三、年轻人破局框架：三字诀&quot;">​</a></h2><h3 id="挪地-→-入局-→-改认知" tabindex="-1">挪地 → 入局 → 改认知 <a class="header-anchor" href="#挪地-→-入局-→-改认知" aria-label="Permalink to &quot;挪地 → 入局 → 改认知&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>行动</th><th>本质</th></tr></thead><tbody><tr><td><strong>① 挪地</strong></td><td>离开原有环境，去更好的地方（北京、上海等）</td><td>改变约束条件 + 扩大信息带宽</td></tr><tr><td><strong>② 入局</strong></td><td>放弃旧状态（考公/打工/等靠要），投身新游戏</td><td>抛弃旧身份，进入正反馈循环</td></tr><tr><td><strong>③ 改认知</strong></td><td>接触新思想，远离迂腐老登，持续升级认知</td><td>认知是破局的起点，不是终点</td></tr></tbody></table><h3 id="三字诀的操作逻辑" tabindex="-1">三字诀的操作逻辑 <a class="header-anchor" href="#三字诀的操作逻辑" aria-label="Permalink to &quot;三字诀的操作逻辑&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>约束条件（环境）→ 行动系统（身份/游戏）→ 认知底座（思维/信息源）</span></span>
<span class="line"><span>     ↑                              ↓</span></span>
<span class="line"><span>     └──────────────────────────────┘</span></span>
<span class="line"><span>       （三者的螺旋提升）</span></span></code></pre></div><ul><li><strong>挪地</strong> ≠ 简单的物理移动，是改变约束条件</li><li><strong>入局</strong> ≠ 盲目创业，是切换行动系统</li><li><strong>改认知</strong> ≠ 读几本书，是持续刷新信息源和思维模型</li></ul><hr><h2 id="四、可关联话题" tabindex="-1">四、可关联话题 <a class="header-anchor" href="#四、可关联话题" aria-label="Permalink to &quot;四、可关联话题&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/career-observation/ai-workplace-paradox.html">AI时代的职场悖论</a> —— 规则变化带来机会与风险</li><li><a href="/zhishiku-reading/topics/career-observation/reverse-ability-ai-era.html">反差能力：AI时代传统从业者的新叙事</a> —— 认知转型方法论</li><li><a href="/zhishiku-reading/topics/entrepreneurship/">创业方向拆解</a> —— 从认知到行动的路径</li></ul><hr><p><em>关联线索：代际思维差异、行业周期认知、年轻人行动框架</em></p>`,29)])])}const b=a(d,[["render",i]]);export{p as __pageData,b as default};
